package com.mfg.erp.controller;import com.mfg.common.api.ApiResponse;import com.mfg.erp.service.ErpP2Service;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/erp") @RequiredArgsConstructor public class ErpP2Controller{private final ErpP2Service s;private ApiResponse<Page<Map<String,Object>>>page(String t,String k,String st,int p,int z){return ApiResponse.ok(s.list(t,k,st,p,z));}
 @PostMapping("/sales-orders/{id}/credit-check")public ApiResponse<Map<String,Object>>credit(@PathVariable long id){return ApiResponse.ok(s.credit(id));}@PostMapping("/sales-orders/{id}/atp")public ApiResponse<List<Map<String,Object>>>atp(@PathVariable long id){return ApiResponse.ok(s.atp(id));}@PostMapping("/sales-orders/{id}/atp/accept")public ApiResponse<List<Map<String,Object>>>acceptAtp(@PathVariable long id,@RequestBody(required=false) Map<String,Object>x){return ApiResponse.ok(s.acceptAtp(id,x==null?null:String.valueOf(x.getOrDefault("reason",""))));}@PostMapping("/sales-orders/{id}/credit-exception")public ApiResponse<?>creditException(@PathVariable long id,@RequestBody Map<String,Object>x){return ApiResponse.ok(s.submitCreditException(id,String.valueOf(x.getOrDefault("reason",""))));}@PostMapping("/sales-orders/{id}/change")public ApiResponse<Void>change(@PathVariable long id,@RequestBody Map<String,Object>x){s.change(id,x);return ApiResponse.ok();}@PostMapping("/sales-orders/{id}/cancel")public ApiResponse<Void>cancel(@PathVariable long id,@RequestBody Map<String,Object>x){s.cancel(id,String.valueOf(x.getOrDefault("reason","")));return ApiResponse.ok();}
 @GetMapping("/credits")public ApiResponse<Page<Map<String,Object>>>credits(@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return page("erp_customer_credit",keyword,status,page,size);}
 @GetMapping("/mrp/runs")public ApiResponse<Page<Map<String,Object>>>runs(@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return page("erp_mrp_run",keyword,status,page,size);}@PostMapping("/mrp/runs")public ApiResponse<Map<String,Object>>run(@RequestBody Map<String,Object>x){return ApiResponse.ok(s.createMrp(x));}@PostMapping("/mrp/runs/{id}/execute")public ApiResponse<Map<String,Object>>execute(@PathVariable long id){return ApiResponse.ok(s.executeMrp(id));}@GetMapping("/mrp/suggestions")public ApiResponse<Page<Map<String,Object>>>suggestions(@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return page("erp_plan_suggestion",keyword,status,page,size);}@PostMapping("/mrp/suggestions/{id}/confirm")public ApiResponse<Map<String,Object>>suggest(@PathVariable long id){return ApiResponse.ok(s.confirmSuggestion(id));}
 @GetMapping("/production-orders/p2")public ApiResponse<Page<Map<String,Object>>>orders(@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return page("erp_prod_order",keyword,status,page,size);}@GetMapping("/production-orders/{id}/kit-check")public ApiResponse<Map<String,Object>>kit(@PathVariable long id){return ApiResponse.ok(s.kitCheck(id));}
 @GetMapping("/receivables")public ApiResponse<Page<Map<String,Object>>>ars(@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return page("erp_receivable",keyword,status,page,size);}@GetMapping("/invoices")public ApiResponse<Page<Map<String,Object>>>invoices(@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return page("erp_invoice",keyword,status,page,size);}@PostMapping("/invoices")public ApiResponse<Map<String,Object>>invoice(@RequestBody Map<String,Object>x){return ApiResponse.ok(s.invoice(x));}@GetMapping("/receipts")public ApiResponse<Page<Map<String,Object>>>receipts(@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return page("erp_receipt",keyword,status,page,size);}@PostMapping("/receipts")public ApiResponse<Map<String,Object>>receipt(@RequestBody Map<String,Object>x){return ApiResponse.ok(s.receipt(x));}@PostMapping("/settlements")public ApiResponse<Void>settle(@RequestBody Map<String,Object>x){s.settle(x);return ApiResponse.ok();}@GetMapping("/payables")public ApiResponse<Page<Map<String,Object>>>payables(@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return page("erp_payable",keyword,status,page,size);}@PostMapping("/payables")public ApiResponse<Map<String,Object>>payable(@RequestBody Map<String,Object>x){return ApiResponse.ok(s.createPayable(x));}@GetMapping("/order-costs/{no}")public ApiResponse<Map<String,Object>>margin(@PathVariable String no){return ApiResponse.ok(s.margin(no));}
}
